 "content": "from collections import Counter


def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    seen = set()
    comps = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == bg or (r, c) in seen:
                continue
            stack, cells = [(r, c)], []
            seen.add((r, c))
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for yy, xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0 <= yy < h and 0 <= xx < w and (yy, xx) not in seen and grid[yy][xx] == color:
                        seen.add((yy, xx))
                        stack.append((yy, xx))
            comps.append((color, cells))
    motif_color, motif = max(comps, key=lambda p: len(p[1]))
    minr, maxr = min(r for r,c in motif), max(r for r,c in motif)
    minc, maxc = min(c for r,c in motif), max(c for r,c in motif)
    ar, ac = (minr + maxr)//2, (minc + maxc)//2
    offsets = [(r-ar,c-ac,grid[r][c]) for r,c in motif]
    markers = [(r,c) for color,cells in comps if color != motif_color for r,c in cells]
    out = [row[:] for row in grid]
    for r,c in markers:
        for dr,dc,color in offsets:
            rr,cc=r+dr,c+dc
            if 0 <= rr < h and 0 <= cc < w:
                out[rr][cc]=color
    return out

if __name__ == '__main__':
